	private static List<String> linkedModels(String ndjson) {
		ObjectMapper mapper = new ObjectMapper();
		List<String> links = new ArrayList<>();
		for (String line : ndjson.split("\\R")) {
			if (line.isBlank()) {
				continue;
			}
			JsonNode record = mapper.readTree(line);
			if ("links".equals(record.path("type").asText())) {
				record.path("values").forEach(value -> links.add(value.asText()));
			}
		}
		return links;
	}

